package com.companages;
import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.MockMvc; import org.springframework.transaction.annotation.Transactional; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc @Transactional class OrganizationCrudIntegrationTest { @Autowired MockMvc mvc; @Autowired ObjectMapper json;
 @Test void organizationCrudLifecycle()throws Exception{String auth=mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Jo\",\"email\":\"jo@example.com\",\"password\":\"password123\"}")).andReturn().getResponse().getContentAsString();String token=json.readTree(auth).get("token").asText();String created=mvc.perform(post("/api/organizations").header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Studio\",\"description\":\"Design\"}")).andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();long id=json.readTree(created).get("id").asLong();mvc.perform(get("/api/organizations").header("Authorization","Bearer "+token)).andExpect(status().isOk()).andExpect(jsonPath("$[0].name").value("Studio"));mvc.perform(put("/api/organizations/"+id).header("Authorization","Bearer "+token).contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Studio 2\",\"description\":\"Engineering\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.name").value("Studio 2"));mvc.perform(delete("/api/organizations/"+id).header("Authorization","Bearer "+token)).andExpect(status().isNoContent());mvc.perform(get("/api/organizations/"+id).header("Authorization","Bearer "+token)).andExpect(status().isNotFound());}
}
